-- MP-0037: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0037: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('jalaluddin-alias','shamshulkahar-mohd-deli','adnan-abu-hassan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0037: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('jelebu','jempol','kuala pilah') and slug not in ('jalaluddin-alias','shamshulkahar-mohd-deli','adnan-abu-hassan')) then raise exception 'MP-0037: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0037:%' and (m.source_type <> 'editorial' or e.slug not in ('jalaluddin-alias','shamshulkahar-mohd-deli','adnan-abu-hassan') or m.import_key not like 'MP-0037:' || e.slug || ':%')) then raise exception 'MP-0037: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'jalaluddin-alias','Jalaluddin Alias','government','Member of the Dewan Rakyat','Jelebu','Negeri Sembilan','Jalaluddin Alias represents Jelebu, Negeri Sembilan, in the Dewan Rakyat. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4165','/portraits/jalaluddin-alias.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P126.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4165"}, {"label": "UMNO · Negeri Sembilan chair, 2 May 2026", "url": "https://malaysiagazette.com/2026/05/02/saya-nak-mampus-pertahankan-kerajaan-perpaduan-jalaluddin/"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'shamshulkahar-mohd-deli','Shamshulkahar Mohd Deli','government','Member of the Dewan Rakyat','Jempol','Negeri Sembilan','Shamshulkahar Mohd Deli represents Jempol, Negeri Sembilan, in the Dewan Rakyat. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4166','/portraits/shamshulkahar-mohd-deli.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P127.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4166"}, {"label": "UMNO · Jempol representative, 22 October 2026", "url": "https://umno-online.my/2026/10/22/jangan-jadikan-isu-dnaa-ahmad-zahid-modal-politik/"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'adnan-abu-hassan','Adnan Abu Hassan','government','Chair of the Special Committee on Corruption; Member of the Dewan Rakyat','Kuala Pilah','Negeri Sembilan','Adnan Abu Hassan represents Kuala Pilah, Negeri Sembilan, in the Dewan Rakyat. Current role: Chair of the Special Committee on Corruption; Member of the Dewan Rakyat. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4168','/portraits/adnan-abu-hassan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P129.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4168"}, {"label": "UMNO · special committee chair appointment, 30 June 2026", "url": "https://umno-online.my/2026/06/30/amanah-baharu-buat-adnan-abu-hassan-pengerusi-jawatankuasa-khas-mengenai-rasuah/"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('jalaluddin-alias','shamshulkahar-mohd-deli','adnan-abu-hassan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0037: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0037:shamshulkahar-mohd-deli:jeram-padang-ramadan','Contribute to Jeram Padang asnaf aid and mosque support','Social Welfare','achieved',null,null,null,null,'2026-02-26','https://umno-online.my/2026/02/26/program-ihya-ramadhan-dun-jeram-padang-meriah-bantuan-asnaf-warga-emas-disalur/','Shamshulkahar represented KPTM in assistance for 96 asnaf recipients and contributed RM30,000 to Masjid Felda Palong 2 plus RM6,000 for iftar.','This party-published handover report covers the stated contributions. The separate 230-person elderly assistance and 30 food-box distribution are not attributed solely to him.','2026-11-09','editorial',false from public.entities e where e.slug='shamshulkahar-mohd-deli' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

